  'help.sales.tabs.title': 'Verkoopstroom',
  'help.sales.tabs.body': 'Hoofdtraject: Offerte → Bestelling → LB → Factuur → Creditnota → Klanten.\nExtra tabbladen (BRC, Proforma, Voorschotten, Betalingen, Sturing) vullen de cyclus aan.',
  'help.purchases.tabs.title': 'Aankoopstroom',
  'help.purchases.tabs.body': 'Hoofdtraject: DPF → CDF → Ontvangsten → Facturen F → AF → Leveranciers.\nBRF en Geparsede docs behandelen leveranciersretouren en OCR-boeking.',

  'help.sales.quote.title': 'Klantofferte',
  'help.sales.quote.n1': 'Voorlopig document zonder voorraad- of boekhoudimpact.',
  'help.sales.quote.body': 'Maak of bewerk een offerte: klant, productregels, hoeveelheden en prijzen.\nDe offerte kan later een bestelling worden volgens de statusregels.',
  'help.sales.quote.rules': 'RG-DV1|Geldigheidsdatum verplicht (standaard 30 dagen).\nRG-DV2|Vrije regels in concept.\nRG-DV3|Een Aanvaarde offerte kan 1 tot N bestellingen genereren.\nRG-DV4|Verlopen: niet meer omzetbaar.\nRG-DV5|Dupliceren mogelijk indien geweigerd of verlopen.',
  'help.sales.quote.example': 'Bv: Offerte 03/08, 30 dagen → verloopt 02/09. Klant Dupont SARL, 3 regels, 2 450€ excl. btw.',
  'help.sales.quote.guide': 'Actieve klant selecteren\nRegels toevoegen (prijs, korting, btw)\nGeldigheidsdatum controleren\nOpslaan en naar klant sturen\nOpvolgen Aanvaard / Geweigerd / Verlopen\nOmzetten naar bestelling indien aanvaard',
  'help.sales.quote.version': 'v1.0.0',

  'help.sales.order.title': 'Klantbestelling',
  'help.sales.order.n1': 'Klantverbintenis; kan voorraad reserveren.',
  'help.sales.order.body': 'Verkooporder gekoppeld aan de klant. Gaat meestal vooraf aan leveringsbonnen en facturatie.',
  'help.sales.order.rules': 'RG-CC1|Actieve klant verplicht; minstens één regel.\nRG-CC2|Indien openstaand + order > kredietplafond → Wacht op goedkeuring.\nRG-CC3|Validatie: nummering, voorraadreservering, velden vergrendeld.\nRG-CC5|Reeds geleverde regels niet wijzigbaar.\nRG-CC9|Klant vast na validatie.',
  'help.sales.order.example': 'Bv: Plafond 10 000€, openstaand 8 500€ → order mag max. 1 500€ zonder financiële goedkeuring.',
  'help.sales.order.guide': 'Klant en adres kiezen\nRegels toevoegen en voorraad controleren\nKredietplafond controleren\nValideren / nummeren\nLeveringen en facturatie opvolgen',
  'help.sales.order.version': 'v1.0.0',
  'help.sales.order.status.Draft': 'Concept: alle velden wijzigbaar. Controleer het kredietplafond vóór validatie.',
  'help.sales.order.status.Confirmed': 'Bevestigd: enkel niet-geleverde regels aanpasbaar. Annulering = reden verplicht.',

  'help.sales.invoice.title': 'Klantfactuur',
  'help.sales.invoice.n1': 'Definitief boekhoudkundig document (klant / verkopen / btw).',
  'help.sales.invoice.body': 'Verkoopfactuur. Kan op één of meer leveringen gebaseerd zijn.\nTotalen excl./btw/incl. worden uit de regels berekend.',
  'help.sales.invoice.rules': 'RG-FC1|Aanmaak vanuit LB en/of bestelling.\nRG-FC3|Validatie: definitieve nummering + boeking + openstaand.\nRG-FC4|Wijziging verboden na validatie (via creditnota).\nRG-FC7|Btw volgens datum, land en artikel.',
  'help.sales.invoice.example': 'Bv: Factuur 15/03, 30 dagen einde maand → vervaldag 30/04.',
  'help.sales.invoice.guide': 'Bron-LB/bestelling selecteren\nPrijzen en btw controleren\nVervaldatum en betaalwijze controleren\nValideren (boeking)\nNaar klant sturen',
  'help.sales.invoice.version': 'v1.0.0',

